/* I2C address -> the ACF half that belongs to it. 0x35 is dev_index 0 and
 * 0x34 is dev_index 1 (see the warning above); anything else gets nothing. */
static inline const uint16_t *
pong_amp_profile_for_addr(uint16_t addr)
{
	switch (addr) {
	case 0x35u: return pong_amp_profile_dev0;
	case 0x34u: return pong_amp_profile_dev1;
	default: return 0;
	}
}

